<?php
namespace App\Http\Controllers\Network;use App\Domain\ApiHub\Models\{TenantApiClient,TenantApiKey,TenantApiQuotaPolicy,TenantApiUsageEvent,TenantApiWebhookDelivery};use App\Http\Controllers\Controller;
final class NetworkApiHubController extends Controller{public function __invoke(){return view('network.api-hub',['clients'=>TenantApiClient::with('tenant')->withCount(['keys'=>fn($q)=>$q->whereNull('revoked_at')])->latest()->paginate(40),'usage'=>TenantApiUsageEvent::where('occurred_at','>=',now()->startOfMonth())->count(),'errors'=>TenantApiUsageEvent::where('occurred_at','>=',now()->startOfMonth())->where('http_status','>=',400)->count(),'failedWebhooks'=>TenantApiWebhookDelivery::whereIn('status',['FAILED','EXHAUSTED'])->count()]);}}
